-- AwardVote Supabase schema
create extension if not exists pgcrypto;
create table if not exists public.award_spaces (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admins (id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,password text not null,is_verified boolean not null default false,otp text,otp_expires timestamptz,reset_password_token text,reset_password_expires timestamptz,award_space_id uuid not null references public.award_spaces(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.settings (id uuid primary key default gen_random_uuid(),award_space_id uuid not null unique references public.award_spaces(id) on delete cascade,voting_start timestamptz,voting_end timestamptz,candidate_can_view_votes boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.candidates (id uuid primary key default gen_random_uuid(),name text not null,image text not null,category text not null,department text not null,votes integer not null default 0 check(votes>=0),slug text not null unique,voting_code text unique,bio text not null default '',award_space_id uuid not null references public.award_spaces(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
-- Safe migration for projects created from an earlier schema.
alter table public.candidates add column if not exists voting_code text;
create unique index if not exists candidates_voting_code_unique_idx on public.candidates(voting_code) where voting_code is not null;
create index if not exists candidates_award_space_idx on public.candidates(award_space_id);create index if not exists candidates_category_idx on public.candidates(award_space_id,category);
create table if not exists public.vote_history (id bigint generated by default as identity primary key,candidate_id uuid not null references public.candidates(id) on delete cascade,votes integer not null check(votes>=0),recorded_at timestamptz not null default now());create index if not exists vote_history_candidate_idx on public.vote_history(candidate_id,recorded_at);
alter table public.award_spaces enable row level security;alter table public.admins enable row level security;alter table public.settings enable row level security;alter table public.candidates enable row level security;alter table public.vote_history enable row level security;
insert into storage.buckets(id,name,public) values('candidate-images','candidate-images',true) on conflict(id) do update set public=excluded.public;drop policy if exists "Public can view candidate images" on storage.objects;create policy "Public can view candidate images" on storage.objects for select to public using(bucket_id='candidate-images');
create table if not exists public.votes (id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,candidate_id uuid not null references public.candidates(id) on delete cascade,candidate_code text,category text not null,voter_hash text not null,quantity integer not null default 1 check(quantity>0),status text not null default 'confirmed' check(status in('pending','confirmed','rejected','refunded')),payment_provider text,payment_reference text,amount_minor bigint,currency text,ip_hash text,user_agent text,created_at timestamptz not null default now(),confirmed_at timestamptz);
alter table public.votes add column if not exists candidate_code text;
create unique index if not exists votes_one_voter_per_category_idx on public.votes(award_space_id,category,voter_hash) where status='confirmed' and payment_reference is null;create unique index if not exists votes_payment_reference_idx on public.votes(payment_provider,payment_reference) where payment_reference is not null;create index if not exists votes_candidate_idx on public.votes(candidate_id,created_at);create index if not exists votes_candidate_code_idx on public.votes(candidate_code,created_at);create index if not exists votes_award_space_idx on public.votes(award_space_id,created_at);
create table if not exists public.vote_adjustments (id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,candidate_id uuid not null references public.candidates(id) on delete cascade,admin_id uuid not null references public.admins(id) on delete restrict,delta integer not null check(delta<>0),reason text not null check(char_length(trim(reason))>=3),previous_total integer not null check(previous_total>=0),new_total integer not null check(new_total>=0),created_at timestamptz not null default now());create index if not exists vote_adjustments_candidate_idx on public.vote_adjustments(candidate_id,created_at);alter table public.votes enable row level security;alter table public.vote_adjustments enable row level security;
-- Give legacy candidates a unique 4-digit code where capacity exists.
do $$ declare r record;c text;begin for r in select id from public.candidates where voting_code is null loop loop c:=lpad((1000+floor(random()*9000))::int::text,4,'0');exit when not exists(select 1 from public.candidates where voting_code=c);end loop;update public.candidates set voting_code=c where id=r.id;end loop;end $$;
alter table public.candidates alter column voting_code set not null;
create or replace function public.cast_vote(p_candidate_id uuid,p_voter_hash text,p_ip_hash text default null,p_user_agent text default null) returns table(vote_id uuid,candidate_id uuid,total_votes integer) language plpgsql security definer set search_path=public as $$ declare v_candidate public.candidates%rowtype;v_settings public.settings%rowtype;v_vote_id uuid;begin select * into v_candidate from public.candidates where id=p_candidate_id for update;if not found then raise exception 'Candidate not found' using errcode='P0002';end if;select * into v_settings from public.settings where award_space_id=v_candidate.award_space_id;if v_settings.id is null or v_settings.voting_start is null or v_settings.voting_end is null then raise exception 'Voting is not configured' using errcode='P0001';end if;if now()<v_settings.voting_start then raise exception 'Voting has not started' using errcode='P0001';end if;if now()>v_settings.voting_end then raise exception 'Voting has ended' using errcode='P0001';end if;insert into public.votes(award_space_id,candidate_id,candidate_code,category,voter_hash,quantity,status,ip_hash,user_agent,confirmed_at) values(v_candidate.award_space_id,v_candidate.id,v_candidate.voting_code,v_candidate.category,p_voter_hash,1,'confirmed',p_ip_hash,left(p_user_agent,500),now()) returning id into v_vote_id;update public.candidates set votes=votes+1,updated_at=now() where id=v_candidate.id returning votes into total_votes;insert into public.vote_history(candidate_id,votes) values(v_candidate.id,total_votes);vote_id:=v_vote_id;candidate_id:=v_candidate.id;return next;exception when unique_violation then raise exception 'You have already voted in this category' using errcode='23505';end;$$;
create or replace function public.confirm_paid_vote(p_payment_provider text,p_payment_reference text) returns table(vote_id uuid,candidate_id uuid,quantity integer,total_votes integer) language plpgsql security definer set search_path=public as $$ declare v_vote public.votes%rowtype;begin select * into v_vote from public.votes where payment_provider=p_payment_provider and payment_reference=p_payment_reference for update;if not found then raise exception 'Payment vote not found';end if;if v_vote.status='confirmed' then vote_id:=v_vote.id;candidate_id:=v_vote.candidate_id;quantity:=v_vote.quantity;select votes into total_votes from public.candidates where id=v_vote.candidate_id;return next;return;end if;if v_vote.status<>'pending' then raise exception 'Payment vote is not pending';end if;update public.votes set status='confirmed',confirmed_at=now() where id=v_vote.id;update public.candidates set votes=votes+v_vote.quantity,updated_at=now() where id=v_vote.candidate_id returning votes into total_votes;insert into public.vote_history(candidate_id,votes) values(v_vote.candidate_id,total_votes);vote_id:=v_vote.id;candidate_id:=v_vote.candidate_id;quantity:=v_vote.quantity;return next;end;$$;
create or replace function public.adjust_candidate_votes(p_candidate_id uuid,p_admin_id uuid,p_delta integer,p_reason text) returns table(candidate_id uuid,previous_total integer,new_total integer) language plpgsql security definer set search_path=public as $$ declare v_candidate public.candidates%rowtype;v_admin public.admins%rowtype;begin if p_delta=0 then raise exception 'Adjustment cannot be zero';end if;if char_length(trim(p_reason))<3 then raise exception 'A reason is required';end if;select * into v_admin from public.admins where id=p_admin_id;if not found then raise exception 'Admin not found';end if;select * into v_candidate from public.candidates where id=p_candidate_id for update;if not found or v_candidate.award_space_id<>v_admin.award_space_id then raise exception 'Candidate not found';end if;previous_total:=v_candidate.votes;new_total:=previous_total+p_delta;if new_total<0 then raise exception 'Vote total cannot be negative';end if;update public.candidates set votes=new_total,updated_at=now() where id=p_candidate_id;insert into public.vote_adjustments(award_space_id,candidate_id,admin_id,delta,reason,previous_total,new_total) values(v_candidate.award_space_id,p_candidate_id,p_admin_id,p_delta,trim(p_reason),previous_total,new_total);insert into public.vote_history(candidate_id,votes) values(p_candidate_id,new_total);candidate_id:=p_candidate_id;return next;end;$$;
revoke all on function public.cast_vote(uuid,text,text,text) from public,anon,authenticated;grant execute on function public.cast_vote(uuid,text,text,text) to service_role;revoke all on function public.confirm_paid_vote(text,text) from public,anon,authenticated;grant execute on function public.confirm_paid_vote(text,text) to service_role;revoke all on function public.adjust_candidate_votes(uuid,uuid,integer,text) from public,anon,authenticated;grant execute on function public.adjust_candidate_votes(uuid,uuid,integer,text) to service_role;
